function run_5g_samples()
%RUN_5G_SAMPLES Regenerate the R2026a-supported 5G NR oracle samples.
%
% This runner intentionally includes only scripts that require MATLAB plus
% 5G Toolbox. LTE and WLAN samples are regenerated by their own Toolboxes,
% which are not assumed to be installed on every oracle host.

script_dir = fileparts(mfilename('fullpath'));
addpath(script_dir);

required_functions = { ...
    'nrCRCEncode', 'nrLDPCEncode', 'nrRateMatchLDPC', 'nrPolarEncode', ...
    'nrSymbolModulate', 'nrLayerMap', 'nrOFDMModulate', 'nrPRBS', ...
    'nrPDSCHDMRS', 'nrCSIRS', 'nrDCIEncode', 'nrPDCCH'};
missing = required_functions(cellfun(@(name) exist(name, 'file') ~= 2, required_functions));
if ~isempty(missing)
    error('wireless_toolbox:Missing5GToolbox', ...
        'R2026a 5G Toolbox functions are missing: %s', strjoin(missing, ', '));
end

scripts = { ...
    'export_base_graphs.m', ...
    'gen_samples_crc.m', ...
    'gen_samples_crc_decode.m', ...
    'gen_samples_demod.m', ...
    'gen_samples_layermap.m', ...
    'gen_samples_ldpc.m', ...
    'gen_samples_nr_phy.m', ...
    'gen_samples_nr_pending.m', ...
    'gen_samples_nr_pdsch.m', ...
    'gen_samples_ofdm_full.m', ...
    'gen_samples_polar.m', ...
    'gen_samples_rate_match_v2.m', ...
    'gen_samples_symbol_mod.m', ...
    'gen_tables.m'};

failures = strings(0, 1);
for index = 1:numel(scripts)
    name = scripts{index};
    fprintf('\n=== %s ===\n', name);
    try
        run(fullfile(script_dir, name));
    catch cause
        failures(end + 1, 1) = string(name) + ": " + string(cause.message); %#ok<AGROW>
        fprintf(2, 'FAIL %s: %s\n', name, cause.message);
    end
end

if ~isempty(failures)
    error('wireless_toolbox:SampleGenerationFailed', ...
        '5G sample regeneration failed.%s%s', newline, strjoin(failures, newline));
end

fprintf('\nR2026a 5G oracle sample generation completed.\n');
end
